const DELIVERY_QUEUE: usize = 256;

#[derive(Clone)]
struct DeliveryState {
    next_epoch: Arc<AtomicU64>,
    next_sequence: Arc<AtomicU64>,
    connections: Arc<std::sync::Mutex<HashMap<u64, mpsc::Sender<DeliveryFrame>>>>,
}

enum DeliveryFrame {
    Event { sequence: u64, event: Event },
    Message(Message),
}

struct DeliveryConnection {
    epoch: u64,
    receiver: mpsc::Receiver<DeliveryFrame>,
}

impl DeliveryState {
    fn new() -> Self {
        Self {
            next_epoch: Arc::new(AtomicU64::new(1)),
            next_sequence: Arc::new(AtomicU64::new(0)),
            connections: Arc::new(std::sync::Mutex::new(HashMap::new())),
        }
    }

    fn register(&self) -> DeliveryConnection {
        let epoch = self.next_epoch.fetch_add(1, Ordering::Relaxed);
        let (sender, receiver) = mpsc::channel(DELIVERY_QUEUE);
        self.connections.lock().unwrap().insert(epoch, sender);
        DeliveryConnection { epoch, receiver }
    }

    fn retire(&self, epoch: u64) {
        self.connections.lock().unwrap().remove(&epoch);
    }

    fn publish(&self, event: Event) {
        let sequence = self.next_sequence.fetch_add(1, Ordering::Relaxed);
        let mut dead = Vec::new();
        let connections = self.connections.lock().unwrap();
        for (&epoch, sender) in connections.iter() {
            if sender
                .try_send(DeliveryFrame::Event {
                    sequence,
                    event: event.clone(),
                })
                .is_err()
            {
                dead.push(epoch);
            }
        }
        drop(connections);
        if !dead.is_empty() {
            let mut connections = self.connections.lock().unwrap();
            for epoch in dead {
                connections.remove(&epoch);
            }
        }
    }

    fn send(&self, epoch: u64, message: Message) -> bool {
        self.connections
            .lock()
            .unwrap()
            .get(&epoch)
            .is_some_and(|sender| sender.try_send(DeliveryFrame::Message(message)).is_ok())
    }

    fn connected(&self) -> bool {
        !self.connections.lock().unwrap().is_empty()
    }
}
struct AudioSlot {
    generation: u64,
    audio: Option<Vec<u8>>,
}
struct AudioQueue {
    next: u64,
    emit: u64,
    slots: BTreeMap<u64, AudioSlot>,
}
impl AudioQueue {
    fn new() -> Self {
        Self {
            next: 0,
            emit: 0,
            slots: BTreeMap::new(),
        }
    }
    fn reserve(&mut self, generation: u64) -> u64 {
        let sequence = self.next;
        self.next += 1;
        self.slots.insert(
            sequence,
            AudioSlot {
                generation,
                audio: None,
            },
        );
        sequence
    }
    fn cancel(&mut self, sequence: u64, generation: u64) -> Vec<Event> {
        self.finish(sequence, generation, Vec::new())
    }

    fn finish(&mut self, sequence: u64, generation: u64, audio: Vec<u8>) -> Vec<Event> {
        let Some(slot) = self.slots.get_mut(&sequence) else {
            return Vec::new();
        };
        if slot.generation == generation {
            slot.audio = Some(audio);
        } else {
            slot.audio = Some(Vec::new());
        }
        let mut ready = Vec::new();
        while let Some(slot) = self.slots.get(&self.emit) {
            if slot.audio.is_none() {
                break;
            }
            let slot = self.slots.remove(&self.emit).expect("audio slot exists");
            if let Some(audio) = slot.audio {
                if !audio.is_empty() {
                    ready.push(Event::Audio {
                        audio,
                        generation: slot.generation,
                        sequence: self.emit,
                    });
                }
            }
            self.emit += 1;
        }
        ready
    }
    fn clear(&mut self) {
        self.slots.clear();
        self.emit = self.next;
    }
}

