const SESSION_TOKEN = process.env.SWITCHBOARD_SESSION_TOKEN ?? "";
const parsedSpeechDeadline = Number.parseInt(
	process.env.SWITCHBOARD_SPEECH_DEADLINE_MS ?? "25000",
	10,
);
